// Benchmark: JSON request binding through Echo's public API (ServeHTTP -> Bind).
// Same program is built against baseline and candidate.
package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"time"

	"github.com/labstack/echo/v5"
)

type target struct {
	ID     int      `json:"id"`
	Name   string   `json:"name"`
	Email  string   `json:"email"`
	Age    int      `json:"age"`
	Active bool     `json:"active"`
	Tags   []string `json:"tags"`
}

type rw struct{ h http.Header }

func (w *rw) Header() http.Header {
	if w.h == nil {
		w.h = http.Header{}
	}
	return w.h
}
func (w *rw) Write(b []byte) (int, error) { return len(b), nil }
func (w *rw) WriteHeader(int)             {}

type body struct{ r *strings.Reader }

func (b body) Read(p []byte) (int, error) { return b.r.Read(p) }
func (body) Close() error                 { return nil }

func main() {
	bodies := []string{
		`{"id":1,"name":"Jon Snow","email":"jon@winterfell.north","age":24,"active":true}`,
		`{"id":2,"name":"Arya Stark","email":"arya@winterfell.north","age":17,"active":false,"tags":["a","b","c","d"]}`,
		`{"id":3,"name":"` + strings.Repeat("x", 4000) + `","email":"e@x","age":1,"active":true}`,
		`{`,
	}
	e := echo.New()
	var last target
	var status int
	e.POST("/", func(c *echo.Context) error {
		var t target
		if err := c.Bind(&t); err != nil {
			status = 400
			return nil
		}
		status = 200
		last = t
		return nil
	})
	r := strings.NewReader("")
	req := httptest.NewRequest(http.MethodPost, "/", r)
	req.Header.Set("Content-Type", "application/json")
	req.Body = body{r}
	w := &rw{}

	var out strings.Builder
	for _, b := range bodies {
		r.Reset(b)
		last = target{}
		e.ServeHTTP(w, req)
		name := last.Name
		if len(name) > 10 {
			name = fmt.Sprint(len(name))
		}
		fmt.Fprintf(&out, "%d %d %s %d %v %v\n", status, last.ID, name, last.Age, last.Active, last.Tags)
	}
	if len(os.Args) > 1 {
		if err := os.WriteFile(os.Args[1], []byte(out.String()), 0o644); err != nil {
			panic(err)
		}
	}

	const n = 400000
	// round-robin over the three valid bodies
	for i := 0; i < 20000; i++ {
		r.Reset(bodies[i%3])
		e.ServeHTTP(w, req)
	}
	start := time.Now()
	for i := 0; i < n; i++ {
		r.Reset(bodies[i%3])
		e.ServeHTTP(w, req)
	}
	fmt.Printf("PERFPROOF {\"value\": %f}\n", time.Since(start).Seconds())
}
EOF
